package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializationConfig;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen1Test {

    private SerializerProvider serializers;
    private BeanProperty property;
    private SerializationConfig config;
    private TestDateTimeSerializer serializer;

    // Concrete implementation for testing abstract class
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean timestamp, DateFormat format) {
            return new TestDateTimeSerializer(handledType(), timestamp, format);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {}

        @Override
        public boolean isEmpty(SerializerProvider serializers, Date value) {
            return false;
        }

        @Override
        protected long _timestamp(Date value) {
            return value.getTime();
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(com.fasterxml.jackson.databind.JavaType type) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) throws JsonMappingException {
        }

        public Boolean getUseTimestamp() { return useTimestamp; }
        public DateFormat getCustomFormat() { return customFormat; }
    }

    // Mocking findFormatOverrides via a spy
    private static class SpiedDateTimeSerializer extends TestDateTimeSerializer {
        private JsonFormat.Value mockFormatValue;

        protected SpiedDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        protected JsonFormat.Value findFormatOverrides(SerializerProvider serializers, BeanProperty property, com.fasterxml.jackson.databind.JavaType handledType) {
            return mockFormatValue;
        }
    }

    @Before
    public void setUp() {
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        config = mock(SerializationConfig.class);
        when(serializers.getConfig()).thenReturn(config);
        when(serializers.getLocale()).thenReturn(Locale.US);
        when(serializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));

        serializer = spy(new SpiedDateTimeSerializer(Date.class, false, null));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = serializer.createContextual(serializers, null);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NoFormatOverrides() throws JsonMappingException {
        doReturn(null).when(serializer).findFormatOverrides(any(), any(), any());
        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertTrue(result instanceof TestDateTimeSerializer);
        assertTrue(((TestDateTimeSerializer) result).getUseTimestamp());
    }

    @Test
    public void testCreateContextual_PatternWithLocaleAndTZ() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.FRANCE);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));

        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        TestDateTimeSerializer res = (TestDateTimeSerializer) result;
        assertFalse(res.getUseTimestamp());
        assertTrue(res.getCustomFormat() instanceof SimpleDateFormat);
        assertEquals(Locale.FRANCE, ((SimpleDateFormat) res.getCustomFormat()).getLocale());
        assertEquals("GMT", ((SimpleDateFormat) res.getCustomFormat()).getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_PatternNoLocaleNoTZ() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);

        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        TestDateTimeSerializer res = (TestDateTimeSerializer) result;
        SimpleDateFormat df = (SimpleDateFormat) res.getCustomFormat();
        assertEquals(Locale.US, df.getLocale());
        assertEquals("UTC", df.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_NoChangeNeeded() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_StdDateFormatWithLocaleAndTZ() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.GERMANY);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("Asia/Tokyo"));
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        StdDateFormat std = new StdDateFormat();
        when(config.getDateFormat()).thenReturn(std);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        StdDateFormat res = (StdDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(Locale.GERMANY, res.getLocale());
        assertEquals("Asia/Tokyo", res.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_SimpleDateFormatWithLocale() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.ITALY);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(Locale.ITALY, res.getLocale());
        assertEquals("yyyy", res.toPattern());
    }

    @Test
    public void testCreateContextual_SimpleDateFormatWithTZ() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(true);
        TimeZone newTz = TimeZone.getTimeZone("EST");
        when(format.getTimeZone()).thenReturn(newTz);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals("EST", res.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_SimpleDateFormatCloneNoChanges() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertNotSame(sdf, res);
        assertEquals("yyyy", res.toPattern());
    }

    @Test(expected = JsonMappingException.class)
    public void testCreateContextual_BadDateFormatType() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.US);
        doReturn(format).when(serializer).findFormatOverrides(any(), any(), any());

        // Use a non-SimpleDateFormat/StdDateFormat
        DateFormat badDf = new DateFormat() {
            @Override public void format(Date date, java.io.Writer out) {}
            @Override public Date parse(String s) { return null; }
            @Override public void format(Date date, java.io.Appendable a) {}
        };
        when(config.getDateFormat()).thenReturn(badDf);

        serializer.createContextual(serializers, property);
        verify(serializers).reportBadDefinition(any(), contains("not a `SimpleDateFormat`"));
    }
}
